/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"sounddesign-level-5","number":5,"title":"Lfo Modulation","skillBand":"Textbook","duration":"From the course textbook","summary":"- Define a Low-Frequency Oscillator (LFO) as a cyclical control signal generator operating below the audible human hearing threshold (<20 Hz). - Control LFO Rate across Free-Running Frequency (Hz) and Tempo-Synced Metric Divisions (straight","modules":[{"id":"sounddesign-m-5-1-1","code":"5.1","title":"LFO Fundamentals","blurb":"- Define a Low-Frequency Oscillator (LFO) as a cyclical control signal generator operating below the audible human hearing threshold (<20 Hz). - Control LFO Rate across Free-Running Frequency (Hz) and Tempo-Synced Metric Divisions (straight","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-13","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Define a <strong>Low-Frequency Oscillator (LFO)</strong> as a cyclical control signal generator operating below the audible human hearing threshold (&lt;20 Hz).","Control LFO <strong>Rate</strong> across <strong>Free-Running Frequency (Hz)</strong> and <strong>Tempo-Synced Metric Divisions</strong> (straight, triplet, dotted).","Calibrate <strong>Modulation Depth / Amount</strong> to control parameter deviation boundaries.","Characterize modulation waveforms: <strong>Sine</strong> (smooth), <strong>Triangle</strong> (linear ramp), <strong>Square</strong> (binary trill), <strong>Sawtooth</strong> (saw drop/ramp), and <strong>Sample &amp; Hold (S&amp;H / Random)</strong> (stepped noise).","Configure LFO <strong>Polarity</strong> (<strong>Bipolar</strong> vs. <strong>Unipolar</strong>) and <strong>Phase Trigger Modes</strong> (<strong>Free-Run</strong>, <strong>Retrigger</strong>, <strong>One-Shot</strong>, <strong>Legato</strong>).","Locate the LFO modulation engine across <code>Drift</code>, <code>Analog</code>, <code>Operator</code>, <code>Vital</code>, and <code>Surge XT</code>."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-1-1","title":"5.1.1 — What an LFO Is","blocks":[{"type":"step","title":"5.1.1 — What an LFO Is","blocks":[{"type":"prose","html":"A <strong>Low-Frequency Oscillator (LFO)</strong> is an oscillator circuit or digital algorithm that operates below the standard threshold of human pitch perception (typically between <strong>0.01 Hz and 20 Hz</strong>)."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ AUDIO OSCILLATOR (440 Hz) ] ======&gt; Routed to Audio Out  ======&gt; [ HEARD AS AUDIBLE PITCH ]\n[ LFO (2 Hz Cycle)          ] ======&gt; Routed to Cutoff/Amp ======&gt; [ HEARD AS CYCLICAL MOVEMENT ]</pre>"},{"type":"prose","html":"Because an LFO cycles slowly, you do not route its output to your speakers as an audio tone. Instead, you route its output voltage as a <strong>control signal</strong> to continuously turn parameters back and forth automatically."},{"type":"list","items":["If an LFO modulates Pitch → <strong>Vibrato</strong>","If an LFO modulates Volume → <strong>Tremolo</strong>","If an LFO modulates Filter Cutoff → <strong>Wobble / Auto-Wah</strong>","If an LFO modulates Stereo Pan → <strong>Auto-Pan</strong>"],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 5.1 (LFO Architecture)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §4 &amp; §6"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-1-2","title":"5.1.2 — Rate / Speed: Hertz vs. Tempo Sync","blocks":[{"type":"step","title":"5.1.2 — Rate / Speed: Hertz vs. Tempo Sync","blocks":[{"type":"prose","html":"The <strong>Rate</strong> parameter dictates how rapidly the LFO completes one full modulation cycle. It operates in two distinct modes:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+----------------------+-----------------------+------------------------------------------------+\n| Rate Mode            | Measurement Units     | Production Application                         |\n+----------------------+-----------------------+------------------------------------------------+\n| **Free-Running (Hz)**| **Hertz ($\\text{Hz}$)**| Organic, un-quantized movement. Natural vibrato|\n|                      | ($0.01\\text{ Hz} - 50\\text{ Hz}$)| ($4-6\\text{ Hz}$), slow ambient drift ($0.1\\text{ Hz}$).|\n+----------------------+-----------------------+------------------------------------------------+\n| **Tempo Synced**     | **Beat Divisions**    | Rhythmic, grid-locked dance music modulation.  |\n|                      | ($1/4, 1/8, 1/16, \\dots$)| Dubstep wubs, rhythmic trance filter gates.    |\n+----------------------+-----------------------+------------------------------------------------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Tempo-Synced Metric Divisions at 140 BPM:\n+-------------------+-------------------+---------------------------------------+\n| Division Label    | Note Length       | Application                           |\n+-------------------+-------------------+---------------------------------------+\n| **$1/1$ (1 Bar)** | Whole Note        | Slow 1-bar filter swell.              |\n| **$1/2$**         | Half Note         | Half-time dubstep pulse.              |\n| **$1/4$**         | Quarter Note      | Standard house 4-on-the-floor pump.   |\n| **$1/8$**         | Eighth Note       | Standard dubstep mid-bass wobble.     |\n| **$1/8\\text{T}$** | Eighth Triplet    | Aggressive triplet riddim bass bounce.|\n| **$1/16$**        | Sixteenth Note    | Fast fluttering stutter / growl.      |\n+-------------------+-------------------+---------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>PML Synthesis – 4 – Modulators</em>, Chapter 8 (LFO Rates &amp; Sync)","<em>Dubstep-Production-Beginner-Live12-Launchkey.md</em>, §6.2"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-1-3","title":"5.1.3 — Depth / Amount: Calibrating Parameter Travel","blocks":[{"type":"step","title":"5.1.3 — Depth / Amount: Calibrating Parameter Travel","blocks":[{"type":"prose","html":"The <strong>Depth</strong> (or <strong>Amount</strong>) control determines the amplitude of the LFO's output signal, governing <strong>how far the target parameter deviates from its resting position</strong>."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Filter Cutoff Travel Under Modulation:\nFrequency (Hz)\n5 kHz |         /\\        /\\\n      |        /  \\      /  \\  [High Depth: Sweeps over a 4 kHz Range]\n      |       /    \\    /    \\\n1 kHz | =====+======+==+======+================= [Base Cutoff Resting Position]\n      |       \\    /    \\    /\n      |        \\  /      \\  /  [Low Depth: Sweeps over a subtle 200 Hz Range]\n200 Hz|         \\/        \\/\n      +----------------------------------------&gt; Time</pre>"},{"type":"list","items":["<strong>At 0% Depth:</strong> The LFO produces no modulation; the target parameter remains completely static.","<strong>At 100% Depth:</strong> The LFO drives the target parameter through its maximum allowable range (e.g., sweeping filter cutoff across the entire 20 Hz - 20 kHz audible spectrum)."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 5.2 (Modulation Scaling)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §4"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-1-4","title":"5.1.4 — Waveforms for Modulation","blocks":[{"type":"step","title":"5.1.4 — Waveforms for Modulation","blocks":[{"type":"prose","html":"The shape of the LFO waveform dictates the <strong>contour and acceleration</strong> of the parameter movement:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">1. SINE / TRIANGLE (Smooth Continuous Wave):\n      /\\        /\\\n  ---+----+----+----+----&gt; Smooth, organic sweeps; natural vibrato, tremolo, and auto-pan.\n      \\/        \\/\n\n2. SQUARE (Binary Switch / Trill):\n   +--+    +--+\n   |  |    |  |\n  -+--+----+--+----+-&gt; Abrupt alternation between two distinct states; octave pitch trills,\n      +----+  +----+   instant rhythm gates, and laser-fast hard panning.\n\n3. SAWTOOTH (Ramp Up / Drop Down):\n     /|   /|   /|\n    / |  / |  / |\n  -+--+-+--+-+--+----&gt; Rhythmic sidechain pump simulation, ramping filter rises, laser drops.\n\n4. SAMPLE &amp; HOLD (S&amp;H / Random Stepped):\n   +--+   +----+\n   |  |   |    |  +--+\n  -+--+---+----+--+--+-&gt; Holds random voltage steps at clock ticks; classic sci-fi computer\n      +---+    +--+     effects, bubbling analog filter glitches, and random pitch arps.</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>PML Synthesis – 4 – Modulators</em>, Chapter 9 (LFO Waveforms)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §4"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-1-5","title":"5.1.5 — Polarity: Bipolar vs. Unipolar","blocks":[{"type":"step","title":"5.1.5 — Polarity: Bipolar vs. Unipolar","blocks":[{"type":"prose","html":"Understanding <strong>Polarity</strong> is critical for placing parameter sweeps accurately:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">BIPOLAR LFO (Oscillates Above and Below Base Center):\n +1.0 |      /\\\n  0.0 | =====+==\\====+======================== [Base Target Parameter Setting]\n -1.0 |          \\/\n      (Target parameter swings equally positive and negative around the center point)\n\nUNIPOLAR LFO (Modulates Only in One Positive Direction):\n +1.0 |      /\\\n  0.0 | =====+==\\====+======================== [Base Target Parameter Setting (Floor)]\n      (Target parameter starts at base value and only travels upwards, never dipping below)</pre>"},{"type":"list","items":["<strong>Bipolar (± 1.0):</strong> Used for <strong>Vibrato</strong> (pitch swings equally sharp and flat around the true note) and <strong>Auto-Pan</strong> (audio swings equally between Left and Right speakers).","<strong>Unipolar (0.0 to +1.0):</strong> Used for <strong>Sidechain Compression Emulation</strong> and <strong>Filter Sweeps</strong>, where the base cutoff serves as the absolute bottom floor and the LFO opens the filter upward."],"ordered":true},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Vital User Manual</em>, Section 5 (LFO Bipolar / Unipolar Modes)","<em>Surge XT User Manual</em>, Section 5 (Modulator Polarity)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-1-6","title":"5.1.6 — Trigger Modes: Free-Run, Retrigger, One-Shot, and Legato","blocks":[{"type":"step","title":"5.1.6 — Trigger Modes: Free-Run, Retrigger, One-Shot, and Legato","blocks":[{"type":"prose","html":"The <strong>Trigger Mode</strong> defines how the LFO synchronizes its cycle phase with incoming MIDI Note-On events:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+----------------------+----------------------------------------------------------------+\n| Trigger Mode         | Operational Phase Behavior                                     |\n+----------------------+----------------------------------------------------------------+\n| **Free-Running**     | The LFO cycles continuously in the background. Hitting a key   |\n|                      | catches the LFO at an arbitrary phase point (organic, loose).  |\n+----------------------+----------------------------------------------------------------+\n| **Retrigger (Sync)** | Every new MIDI key press instantly resets the LFO phase to     |\n|                      | $0^\\circ$ (ensures every bass hit strikes with identical punch).|\n+----------------------+----------------------------------------------------------------+\n| **One-Shot**         | The LFO plays through one single cycle and halts, converting   |\n|                      | the LFO into a custom looping envelope.                        |\n+----------------------+----------------------------------------------------------------+\n| **Legato**           | Retriggers phase only on the first note; overlapping legato    |\n|                      | notes continue the existing modulation cycle without resetting.|\n+----------------------+----------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Dance Music Rule:</strong> Always set LFOs to <strong>Retrigger</strong> on dubstep wobbles and rhythmic basslines so that every drop hit strikes on beat with identical punch."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 5.3 (LFO Phase Sync)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §4"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-1-7","title":"5.1.7 — Finding the LFO Section Across Studio Engines","blocks":[{"type":"step","title":"5.1.7 — Finding the LFO Section Across Studio Engines","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------+-----------------------------------------------------------------------+\n| Engine        | LFO Section Navigation &amp; Architecture                                 |\n+---------------+-----------------------------------------------------------------------+\n| **`Drift`**   | Right-center section: Dedicated **LFO** panel with Waveform selector,  |\n|               | Rate ($\\text{Hz}$ / Synced), Retrigger toggle, and Mod Target dropdown.|\n+---------------+-----------------------------------------------------------------------+\n| **`Analog`**  | Central sub-panel: **LFO 1** and **LFO 2**. Displays Rate, Waveform,   |\n|               | Sync, and independent routing sliders to Osc 1/2, Filter 1/2, and Amp.|\n+---------------+-----------------------------------------------------------------------+\n| **`Operator`**| Dedicated **LFO** block (bottom-left shell). Features internal routing|\n|               | amounts to ABCD Pitch, Filter Cutoff, and Volume with Dest A/B slots. |\n+---------------+-----------------------------------------------------------------------+\n| **`Vital`**   | Middle tier: **LFO 1, 2, 3, 4**. Fully graphical Bezier curve display |\n|               | with Drag-and-Drop routing to any knob on the interface.             |\n+---------------+-----------------------------------------------------------------------+\n| **`Surge XT`**| Bottom modulation routing bar: **LFO 1 through 6** (Voice LFOs) and   |\n|               | **Scene LFOs** (Global). Click LFO button, then drag blue slider.    |\n+---------------+-----------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 23","<em>Vital User Manual</em>, Section 5","<em>Surge XT User Manual</em>, Section 5"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-5-2-2","code":"5.2","title":"Destinations and Musical Results","blurb":"- Map and execute the seven primary LFO modulation routing destinations: Pitch, Volume / VCA, Filter Cutoff, Stereo Pan, Pulse Width, Wavetable Position, and Resonance. - Differentiate musical vibrato (Rate = 4.5 - 6.0 Hz, Depth = 5-15 cent","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-14","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Map and execute the seven primary LFO modulation routing destinations: <strong>Pitch</strong>, <strong>Volume / VCA</strong>, <strong>Filter Cutoff</strong>, <strong>Stereo Pan</strong>, <strong>Pulse Width</strong>, <strong>Wavetable Position</strong>, and <strong>Resonance</strong>.","Differentiate musical vibrato (Rate = 4.5 - 6.0 Hz, Depth = 5-15 cents) from sound-effects sirens.","Synthesize dubstep/bass wobbles (<strong>wubs</strong>) by locking LFO rates to tempo-synced metric subdivisions.","Formulate and execute <strong>The Modulation Mindset</strong>: the universal 4-variable sound design formula (Source → Destination → Depth → Rate)."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-2-1","title":"5.2.1 — LFO → Pitch: Vibrato vs. Sirens / FX","blocks":[{"type":"step","title":"5.2.1 — LFO → Pitch: Vibrato vs. Sirens / FX","blocks":[{"type":"prose","html":"Modulating an oscillator's pitch with an LFO produces two vastly different acoustic results depending strictly on calibration:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+------------------+-----------------------+-----------------------+----------------------------+\n| Application      | LFO Rate              | Modulation Depth      | Musical Result             |\n+------------------+-----------------------+-----------------------+----------------------------+\n| **Vibrato**      | $4.5\\text{ Hz} - 6.5\\text{ Hz}$| **$5 - 20\\text{ cents}$**| Natural acoustic vocal /   |\n|                  | (Free-running Sine)   | (Micro-tuning scale)  | string instrument richness.|\n+------------------+-----------------------+-----------------------+----------------------------+\n| **Siren / FX**   | $0.2\\text{ Hz} - 2\\text{ Hz}$| **$+12 \\text{ to } +24\\text{ st}$**| Dramatic sci-fi alarms,    |\n|                  | (Square / Saw / Triangle)| (Full octaves)      | arcade dive-bombs, lasers. |\n+------------------+-----------------------+-----------------------+----------------------------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Vibrato Waveform Contour:\nPitch (Cents)\n +15 c |      /\\        /\\        /\\   [Micro-deviation creates acoustic warmth without]\n   0 c | =====+==\\======+==\\======+==\\== [sounding out of tune]\n -15 c |          \\/        \\/        \\/</pre>"},{"type":"prose","html":"<strong>The Vibrato Rule:</strong> If your vibrato sounds like a comedy police siren, your LFO Depth is set too high. Human vibrato operates within a fraction of a semitone (10-15 cents)."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 5.4 (Pitch Modulation)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §4"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-2-2","title":"5.2.2 — LFO → Volume / VCA: Tremolo vs. Rhythmic Gating","blocks":[{"type":"step","title":"5.2.2 — LFO → Volume / VCA: Tremolo vs. Rhythmic Gating","blocks":[{"type":"prose","html":"Modulating the amplifier stage (VCA) with an LFO alters loudness over time:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ LFO ] ===(Modulation Amount)===&gt; [ AMPLIFIER (VCA) GAIN ]</pre>"},{"type":"list","items":["<strong>Tremolo (Continuous Modulation):</strong> A smooth Sine or Triangle LFO cycling at 3-8 Hz creates a classic vintage guitar tremolo or Rhodes electric piano flutter.","<strong>Rhythmic Chopping / Trance Gate (Binary Modulation):</strong> A tempo-synced <strong>Square Wave LFO</strong> running at 1/16th notes with 100% unipolar depth cuts the audio volume completely to zero on every off-beat, transforming a sustained pad into an energetic rhythmic gate."],"ordered":true},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>PML Synthesis – 4 – Modulators</em>, Chapter 10 (Amplitude Modulation)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §4"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-2-3","title":"5.2.3 — LFO → Filter Cutoff: Wobble / Wub vs. Subtle Breathing","blocks":[{"type":"step","title":"5.2.3 — LFO → Filter Cutoff: Wobble / Wub vs. Subtle Breathing","blocks":[{"type":"prose","html":"Modulating a low-pass or band-pass filter cutoff with an LFO is the core mechanism of modern bass music:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ TEMPO-SYNCED LFO (1/8th Note) ] ===&gt; [ LOW-PASS FILTER CUTOFF (fc) ]\n                                                    |\n                                                    v\n                                    [ RHYTHMIC \"WUB-WUB\" BASSLINE ]</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+----------------------+-----------------------+-------------------+----------------------------+\n| Target Aesthetic     | LFO Rate &amp; Shape      | Base Filter Cutoff| Modulation Depth           |\n+----------------------+-----------------------+-------------------+----------------------------+\n| **Subtle Breathing** | $0.2\\text{ Hz}$ (Sine)| $800\\text{ Hz}$   | Low ($15\\% - 30\\%$)        |\n| (Ambient Pad Motion) | Free-Running          |                   | Smooth, gentle warmth.     |\n+----------------------+-----------------------+-------------------+----------------------------+\n| **Dubstep Wub**      | $1/4, 1/8, 1/16$      | $150\\text{ Hz}$   | High ($70\\% - 95\\%$)       |\n| (Heavy Mid-Bass)     | Tempo-Synced (Saw/Sine)| (Floor low)      | Aggressive rhythmic vocal. |\n+----------------------+-----------------------+-------------------+----------------------------+</pre>"},{"type":"prose","html":"<strong>Try It (<code>Drift</code> Wobble Bass):</strong>"},{"type":"list","items":["In <code>Drift</code>, set Osc 1 to <strong>Saw</strong>, tuned down to -1 Octave.","Set Filter to <strong>Low-pass LP12</strong>, Cutoff low (250 Hz), Resonance to 0.45.","Route <strong>LFO</strong> to <code>Filter Cutoff</code>. Switch LFO Mode from Hz to <strong>Sync</strong>.","Set LFO Rate to <strong>1/8</strong> and Depth to <strong>0.80</strong>.","Hold a low note (D_1). You have constructed the fundamental half-time dubstep/drum &amp; bass wobble mechanism."],"ordered":true},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Dubstep-Production-Beginner-Live12-Launchkey.md</em>, §6.2 (Stock Wobble Starter)","<em>Drum-and-Bass-Production-Knowledgebase.md</em>, §6"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-2-4","title":"5.2.4 — LFO → Pan: Auto-Pan and Stereo Movement","blocks":[{"type":"step","title":"5.2.4 — LFO → Pan: Auto-Pan and Stereo Movement","blocks":[{"type":"prose","html":"Modulating the stereo pan position of an oscillator or synth voice moves the sound across the left and right stereo field:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Left  |      /\\\nCenter| =====+==\\======+================ [Bipolar Pan Modulation]\nRight |          \\/</pre>"},{"type":"list","items":["<strong>Gentle Shimmer:</strong> Slow rate (0.3 Hz), moderate depth (30%) on a secondary pad oscillator creates broad spatial depth without displacing the core mix center.","<strong>Fast Rotary Speaker:</strong> Rate at 6 Hz, triangle wave, mapped across an organ patch models a vintage rotating Leslie speaker cabinet.","<strong>Warning for Basses:</strong> <strong>NEVER route an LFO to Pan on low-end frequencies (&lt;120 Hz)</strong>. Sub-bass must remain strictly mono and centered to prevent destructive phase cancellation in club sound systems."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 28 (Audio Effect Reference: Auto Pan)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §4"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-2-5","title":"5.2.5 — LFO → Pulse Width (PWM Re-examined)","blocks":[{"type":"step","title":"5.2.5 — LFO → Pulse Width (PWM Re-examined)","blocks":[{"type":"prose","html":"As mastered in Section 2.2, routing a slow, free-running LFO (0.2 - 0.8 Hz) to the <strong>Pulse Width</strong> of a square wave creates continuous internal phase cancellations."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ LFO (0.5 Hz Triangle) ] ===&gt; [ OSCILLATOR 1 PULSE WIDTH ]\n                                           |\n                                           v\n                          [ Continuous Harmonic Re-balancing ]\n                                           |\n                                           v\n                             [ Thick Dual-Oscillator Illusion ]</pre>"},{"type":"prose","html":"This represents the most CPU-efficient method for generating thick, chorus-like synthesizer leads and string pads on single-oscillator architectures."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 5.5 (PWM Modulation)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-2-6","title":"5.2.6 — LFO → Wavetable Position: Continuous Timbral Morph","blocks":[{"type":"step","title":"5.2.6 — LFO → Wavetable Position: Continuous Timbral Morph","blocks":[{"type":"prose","html":"In wavetable synthesizers (<code>Vital</code>, <code>Surge XT</code>), routing an LFO to <strong>Wavetable Position (WT Pos)</strong> allows the synth to continuously cycle through dozens of distinct single-cycle waveforms:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ LFO 1 (1 Bar Synced Ramp) ] ===&gt; [ VITAL WAVETABLE POSITION ]\n                                                  |\n                                                  v\n                              [ Smooth 3D Interpolation Across Frames ]\n                                                  |\n                                                  v\n                             [ Evolving Futuristic Morphing Texture ]</pre>"},{"type":"prose","html":"Unlike filtering (which can only <em>remove</em> frequencies), wavetable position modulation actively <em>introduces, shifts, and morphs</em> the raw harmonic content at the source."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Vital User Manual</em>, Section 5 (Wavetable LFO Modulation)","<em>Surge XT User Manual</em>, Section 5"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-2-7","title":"5.2.7 — LFO → Resonance: Vocal Formant Movement","blocks":[{"type":"step","title":"5.2.7 — LFO → Resonance: Vocal Formant Movement","blocks":[{"type":"prose","html":"Modulating <strong>Filter Resonance (Q)</strong> with an LFO creates dramatic dynamic emphasis:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Amplitude\n  ^\n  |        /\\  &lt;--- [Resonant peak dynamically rises and falls over time]\n  |       /  \\\n  +------+----+------------------------&gt; Frequency</pre>"},{"type":"prose","html":"When resonance is modulated across a low-pass or band-pass filter while the cutoff is also moving, the sound transitions between smooth analog warmth and screaming vocal-like formant peaks (essential in neurofunk and riddim bass design)."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Surge XT User Manual</em>, Section 4 &amp; 5","<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 5.6"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-2-8","title":"5.2.8 — The Modulation Mindset: Who Controls What, How Much, and How Fast?","blocks":[{"type":"step","title":"5.2.8 — The Modulation Mindset: Who Controls What, How Much, and How Fast?","blocks":[{"type":"prose","html":"Every modulation in sound design—no matter how complex the synthesizer—reduces to answering four deterministic questions:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                         THE FOUR-VARIABLE MODULATION FORMULA                  |\n+-------------------+-----------------------------------------------------------+\n| 1. **WHO?**       | **Modulation Source:** LFO 1, Env 2, Velocity, Mod Wheel. |\n+-------------------+-----------------------------------------------------------+\n| 2. **WHAT?**      | **Modulation Destination:** Cutoff, Pitch, Volume, Pan, PW.|\n+-------------------+-----------------------------------------------------------+\n| 3. **HOW MUCH?**  | **Modulation Depth:** Subtly ($\\pm 5\\%$) vs. Max ($\\pm 100\\%$).|\n+-------------------+-----------------------------------------------------------+\n| 4. **HOW FAST?**  | **Modulation Rate / Time:** $0.1\\text{ Hz}$ vs. $1/8\\text{th}$ Sync vs. $50\\text{ ms}$ Decay.|\n+-------------------+-----------------------------------------------------------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ WHO: LFO 1 (Sine) ] ===( HOW FAST: 1/8th Note )===&gt; [ WHAT: Filter Cutoff ] ===( HOW MUCH: +75% )===&gt; OUTPUT</pre>"},{"type":"prose","html":"Whenever you hear movement in a professional patch, isolate these four variables systematically to reverse-engineer the sound."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §4 (The Modulation Mindset)","<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 5.7"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-5-3-3","code":"5.3","title":"Performance Modulation","blurb":"- Map and assign standard physical MIDI performance controllers: Velocity, Modulation Wheel (CC 1), Pitch Bend, and Aftertouch / Channel Pressure. - Configure Pitch Bend Range parameters (± 2 semitones for leads vs. ± 12 to ± 24 semitones f","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-15","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Map and assign standard physical MIDI performance controllers: <strong>Velocity</strong>, <strong>Modulation Wheel (CC 1)</strong>, <strong>Pitch Bend</strong>, and <strong>Aftertouch / Channel Pressure</strong>.","Configure <strong>Pitch Bend Range</strong> parameters (± 2 semitones for leads vs. ± 12 to ± 24 semitones for bass glides).","Deploy <strong>Keytracking</strong> as an expressive modulation source across filter cutoff, spatial panning, and envelope decay rates.","Execute the canonical <strong>Three-Destination Modulation Drill</strong> (identifying vibrato, tremolo, and wobble by ear).","Complete the <strong>Gate D Self-Assessment Checkpoint</strong>."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-3-1","title":"5.3.1 — Velocity: Dynamic Physical Expression","blocks":[{"type":"step","title":"5.3.1 — Velocity: Dynamic Physical Expression","blocks":[{"type":"prose","html":"<strong>MIDI Velocity</strong> measures how hard or fast a physical key is struck on a scale from <strong>1 to 127</strong>. "},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ PHYSICAL KEY STRIKE ] ===(Velocity Value: 1 to 127)===&gt; [ MODULATION MATRIX ]\n                                                                  |\n              +---------------------------------------------------+-----------------------------------+\n              |                                                   |                                   |\n              v                                                   v                                   v\n    [ Target: Amp Volume ]                            [ Target: Filter Cutoff ]          [ Target: Env Attack Time ]\n (Harder = Louder Volume)                            (Harder = Brighter Tone)           (Harder = Faster Transient)</pre>"}]},{"type":"step","title":"Standard Velocity Routing Configurations:","blocks":[{"type":"list","items":["<strong>Velocity → Volume (VCA):</strong> Soft strikes play quietly; hard strikes play loudly (standard acoustic dynamics).","<strong>Velocity → Filter Cutoff (VCF):</strong> Soft strikes remain warm and dark; hard strikes open the filter to reveal full harmonic brightness.","<strong>Velocity → Pitch Envelope Amount:</strong> On a synth kick or 808, harder velocity increases the transient pitch drop for an aggressive chest thump."],"ordered":true},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 5.8 (Velocity Mapping)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §4"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-3-2","title":"5.3.2 — Modulation Wheel (MIDI CC 1): The Primary Performance Controller","blocks":[{"type":"step","title":"5.3.2 — Modulation Wheel (MIDI CC 1): The Primary Performance Controller","blocks":[{"type":"prose","html":"The physical <strong>Modulation Wheel</strong> on the Novation Launchkey MK4 transmits standard <strong>MIDI Continuous Controller 1 (CC 1)</strong> data (0 - 127)."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ MOD WHEEL (CC 1) ] ===(0 to 127)===&gt; [ VITAL / OPERATOR MATRIX ] ===&gt; [ ASSIGNED TARGET ]</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+------------------------------+----------------------------------------------------------------+\n| Mod Wheel Assignment         | Performance Function                                           |\n+------------------------------+----------------------------------------------------------------+\n| **Mod Wheel $\\rightarrow$ LFO Depth**| Wheel fully down ($0$) = zero vibrato; as you push the wheel   |\n|                              | up, rich expressive vibrato or wobble increases proportionally.|\n+------------------------------+----------------------------------------------------------------+\n| **Mod Wheel $\\rightarrow$ Filter Cutoff**| Manual filter sweep controller during live performance.    |\n+------------------------------+----------------------------------------------------------------+\n| **Mod Wheel $\\rightarrow$ Wavetable Pos**| Morph between clean and distorted wavetable frames live.   |\n+------------------------------+----------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Standard Studio Practice:</strong> Assign the Mod Wheel to modulate <strong>LFO Depth</strong> on lead and vocal patches so that vibrato is applied intentionally by the performer rather than cycling continuously."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Novation Launchkey MK4 61 User Guide</em>, Chapter 3","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §9"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-3-3","title":"5.3.3 — Pitch Bend: Range Setting and Glides","blocks":[{"type":"step","title":"5.3.3 — Pitch Bend: Range Setting and Glides","blocks":[{"type":"prose","html":"The <strong>Pitch Bend Wheel</strong> is a spring-loaded controller that automatically returns to its center point (0) when released. It transmits high-resolution pitch-shift data."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+------------------+-----------------------+----------------------------------------------------+\n| Application      | Pitch Bend Semi Range | Musical Execution                                  |\n+------------------+-----------------------+----------------------------------------------------+\n| **Solo Leads**   | **$\\pm 2\\text{ Semitones}$**| Accurate, controlled guitar-style whole-step and  |\n|                  |                       | half-step pitch bends without missing the note.    |\n+------------------+-----------------------+----------------------------------------------------+\n| **Bass Slides / 808**| **$\\pm 12\\text{ to } \\pm 24\\text{ st}$**| Full one-to-two octave glides and pitch dive-bombs|\n|                  |                       | characteristic of modern trap and drill basslines. |\n+------------------+-----------------------+----------------------------------------------------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Pitch Bend Wheel:\n +1.0 |   Push Up   ---&gt; Pitch Bends Sharp (+2 st or +12 st)\n  0.0 |=== Center   ---&gt; True Un-altered Musical Pitch (Spring Loaded)\n -1.0 |  Pull Down  ---&gt; Pitch Bends Flat (-2 st or -12 st)</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §5 &amp; §9","<em>Dubstep-Production-Beginner-Live12-Launchkey.md</em>, §6.1"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-3-4","title":"5.3.4 — Aftertouch / Channel Pressure","blocks":[{"type":"step","title":"5.3.4 — Aftertouch / Channel Pressure","blocks":[{"type":"prose","html":"<strong>Aftertouch</strong> (or <em>Channel Pressure</em>) generates modulation data when a performer presses <em>deeper</em> into a key <strong>after</strong> the note has already been struck and held down."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ NOTE ONSET (Key Struck) ] ===&gt; [ HOLD NOTE ] ===&gt; [ SQUEEZE KEY DEEPER ] ===&gt; [ AFTERTOUCH TRIGGERED ]\n                                                                                       |\n                                                                                       v\n                                                                       [ Opens Filter / Adds Vibrato ]</pre>"},{"type":"list","items":["Allows a keyboard player to introduce expressive filter opening, distortion drive, or vibrato with physical finger pressure without taking their left hand off the keyboard to reach for the mod wheel."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Novation Launchkey MK4 61 User Guide</em>, Chapter 3 (Pad &amp; Key Aftertouch)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §9"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-3-5","title":"5.3.5 — Keytracking as a Universal Modulation Source","blocks":[{"type":"step","title":"5.3.5 — Keytracking as a Universal Modulation Source","blocks":[{"type":"prose","html":"While Section 3.2 introduced keytracking to scale filter cutoff, <strong>MIDI Note Pitch (Keytracking)</strong> can modulate any parameter inside modern synthesis engines:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ KEYBOARD NOTE PITCH (Low C1 to High C6) ]\n                    |\n                    +===&gt; [ Filter Cutoff ] ======&gt; High notes open filter (Maintains brightness)\n                    |\n                    +===&gt; [ Stereo Pan ] =========&gt; Low notes pan Left, High notes pan Right (Piano spread)\n                    |\n                    +===&gt; [ Envelope Decay Time ] =&gt; High notes have shorter decay (Models acoustic strings)</pre>"},{"type":"list","items":["<strong>Keytrack → Pan:</strong> High notes are mapped slightly to the right, low notes to the left, replicating the natural acoustic spatial layout of an 88-key grand piano.","<strong>Keytrack → Envelope Decay:</strong> Higher-pitched acoustic strings contain less physical mass and therefore decay faster than heavy low strings. Routing Keytrack to Amp Decay (-Amount) automatically tightens higher notes."],"ordered":true},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 5.9 (Advanced Keytracking)","<em>Surge XT User Manual</em>, Section 5"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-3-6","title":"5.3.6 — The Three-Destination Modulation Drill","blocks":[{"type":"step","title":"5.3.6 — The Three-Destination Modulation Drill","blocks":[{"type":"prose","html":"To cement modulation literacy, program an initialized subtractive patch in <code>Drift</code> or <code>Analog</code> and cycle through the three core destinations:"}]},{"type":"step","title":"Execution Protocol:","blocks":[{"type":"list","items":["Load initialized <code>Drift</code>. Set Osc 1 to <strong>Saw</strong>, Filter Cutoff to 600 Hz.","Configure <strong>LFO 1</strong> to a 4 Hz Sine wave with moderate Depth (0.50).","Route LFO to <strong>Pitch</strong> → Say aloud: <strong>\"VIBRATO\"</strong> (Pitch wavers).","Re-route LFO to <strong>Volume / Amp</strong> → Say aloud: <strong>\"TREMOLO\"</strong> (Loudness pulses).","Re-route LFO to <strong>Filter Cutoff</strong> → Say aloud: <strong>\"WOBBLE / WUB\"</strong> (Brightness opens and closes)."],"ordered":true},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §15 (Exercise C)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-5-3-7","title":"5.3.7 — Gate D: Self-Assessment Checkpoint","blocks":[{"type":"step","title":"5.3.7 — Gate D: Self-Assessment Checkpoint","blocks":[{"type":"prose","html":"Before advancing to <strong>Module 6 (Voices, Thickness, and Signal Flow)</strong>, verify your modulation competencies:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                             GATE D CHECKLIST                                  |\n+-------------------------------------------------------------------------------+\n| [ ] 1. The Three Destination Audit:                                           |\n|     Route an LFO to Pitch, Volume, and Filter Cutoff on an initialized synth. |\n|     Can you identify Vibrato, Tremolo, and Wobble by ear with 100% accuracy?  |\n|                                                                               |\n| [ ] 2. Sync vs. Hertz Calculation:                                            |\n|     Can you explain the difference between a free-running 5 Hz LFO and a      |\n|     tempo-synced 1/8th note LFO, and when to use each in production?          |\n|                                                                               |\n| [ ] 3. Polarity Mapping:                                                      |\n|     Can you explain why Vibrato requires a Bipolar LFO while a Sidechain pump |\n|     emulation requires a Unipolar LFO?                                        |\n|                                                                               |\n| [ ] 4. Retrigger Discipline:                                                  |\n|     Can you explain why LFO Retrigger mode must be enabled on rhythmic bass   |\n|     wobbles to prevent off-beat phase drift?                                  |\n|                                                                               |\n| [ ] 5. The Modulation Formula:                                                |\n|     Can you state the 4-variable modulation formula from memory:              |\n|     (Who / Source -&gt; What / Dest -&gt; How Much / Depth -&gt; How Fast / Rate)?     |\n+-------------------------------------------------------------------------------+</pre>"},{"type":"prose","html":"If all 5 criteria are verified by ear and manual execution, <strong>Gate D is passed</strong>. Proceed to <strong>Module 6</strong>."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound Design Foundations Syllabus</em>, §3 (Gate D Definition)"],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
